import { Badge } from '@/components/ui/badge';
import { LinkButton } from '@/components/ui/button';
import { Empty, EmptyContent, EmptyDescription, EmptyHeader, EmptyTitle } from '@/components/ui/empty';

/** One call-to-action button: its Writer label and where it goes. */
export interface CallToActionLink { label: string; href: string }

/** The inputs of `sections.call-to-action`: the contract's copy fields, display-ready. */
export interface CallToActionInput {
  header: { title: string; eyebrow?: string; description?: string };
  actions: { primary: CallToActionLink; secondary?: CallToActionLink };
}

/** `sections.call-to-action`: a centred heading, description and one or two actions, the stock aria-nova empty layout. */
export default function CallToActionSection({ header, actions, ...provenance }: CallToActionInput & { [marker: `data-clossys-${string}`]: string }) {
  return <Empty {...provenance}>
    <EmptyHeader>
      {header.eyebrow ? <Badge variant="secondary">{header.eyebrow}</Badge> : null}
      <EmptyTitle role="heading" aria-level={2}>{header.title}</EmptyTitle>
      {header.description ? <EmptyDescription>{header.description}</EmptyDescription> : null}
    </EmptyHeader>
    <EmptyContent>
      <LinkButton href={actions.primary.href} size="lg">{actions.primary.label}</LinkButton>
      {actions.secondary ? <LinkButton href={actions.secondary.href} size="lg" variant="outline">{actions.secondary.label}</LinkButton> : null}
    </EmptyContent>
  </Empty>;
}
